// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.skill.sandboximport com.roshan.persona.common.Result/** * NOUS — QuickJS sandbox interface (Fixes #21 — Rhino replaced with QuickJS). * * Sandboxed JavaScript execution environment for custom (self-modifying) skills. * QuickJS is used instead of Rhino because: *   - Full ES2023 support (Promises, async/await, ESM modules) *   - 30ms startup (vs Rhino's 200ms) *   - 2MB memory footprint (vs Rhino's 8MB) *   - Built-in sandboxing (memory limit, time limit, stack limit) *   - Active maintenance (Bellard) * * Only available in `dev` and `internal` flavors (sideload builds). * Disabled in `prod` flavor (Play Store) per ADR 0008. * * Real implementation: :feature:selfmodify's `RhinoJsSandbox` (dev/internal * flavors only). Prod flavor provides NO `JsSandbox` binding — ADR 0008's * "Play Store safe" requirement is met by NOT bundling any JS engine in the * prod APK. When a future Brain component needs `JsSandbox` in prod, the * `:app` module's prod source set should provide an explicit no-op impl. * * Test fakes: `FakeJsSandbox` + `NoOpJsSandbox` in * `src/test/kotlin/.../skill/sandbox/`. * * @see <a href="docs/spec/module2-spec-review.pdf">§6.3 JS Engine Switch</a> */interface JsSandbox {    /**     * Execute a JavaScript script in the sandbox.     *     * @param script the JS code to execute     * @param params parameters passed to the script (available as `params` global)     * @param limits sandbox resource limits     * @return [Result] containing the script's return value (as String), or error     */    suspend fun execute(        script: String,        params: Map<String, Any>,        limits: SandboxLimits = SandboxLimits.DEFAULT,    ): Result<String>    /** Check if the sandbox is available (false in prod flavor). */    fun isAvailable(): Boolean}/** Sandbox resource limits. */data class SandboxLimits(    val maxMemoryBytes: Long = 32 * 1024 * 1024,  // 32MB    val maxStackBytes: Long = 1024 * 1024,         // 1MB    val timeoutMs: Long = 5_000,                    // 5 seconds    val allowedApis: Set<JsApi> = setOf(JsApi.HTTP, JsApi.CLIPBOARD),) {    companion object {        val DEFAULT = SandboxLimits()        val STRICT = SandboxLimits(            maxMemoryBytes = 16 * 1024 * 1024,            maxStackBytes = 512 * 1024,            timeoutMs = 2_000,            allowedApis = setOf(JsApi.CLIPBOARD),  // no HTTP in strict mode        )    }}/** APIs that JS skills can access (allowlisted). */enum class JsApi {    HTTP,          // fetch() for web requests    CLIPBOARD,     // read/write clipboard    FILE_READ,     // read files (scoped to app storage)    FILE_WRITE,    // write files (scoped to app storage)    NOTIFICATION,  // post notifications    TTS,           // text-to-speech}